prompt:
{
  "model": "ministral-8b-latest",
  "messages": [
    {
      "role": "system",
      "content": "Extract the competition information from the provided text. Return null for any field that cannot be found."
    },
    {
      "role": "user",
      "content": "{{ $json.text }}"
    }
  ],
  "response_format": {
    "type": "json_schema",
    "json_schema": {
      "schema": {
        "properties": {
          "title": {
            "title": "Title",
            "type": "string",
            "description": "Competition title. Return null if not found."
          },
          "organizer": {
            "title": "Organizer",
            "items": {
              "type": "string"
            },
            "type": "array",
            "description": "Competition organizer, single or multiple. Return null if not found."
          },
          "categories": {
            "title": "Categories",
            "items": {
              "type": "string",
              "enum": [
                "Akademik & Sains",
                "Teknologi & IT",
                "Seni & Kreatif",
                "Bisnis & Startup",
                "Olahraga & E-sports",
                "Sastra & Bahasa",
                "Sosial & Lingkungan",
                "Keagamaan",
                "Gaya Hidup & Hobi",
                "Lainnya"
              ]
            },
            "type": "array",
            "description": "Competition category. Return null if not found."
          },
          "level": {
            "title": "Level",
            "items": {
              "type": "string",
              "enum": [
                "SD",
                "SMP",
                "SMA",
                "Mahasiswa",
                "Umum"
              ]
            },
            "type": "array",
            "description": "Participant level. Return null if not found."
          },
          "startDate": {
            "title": "Start Date",
            "type": "string",
            "description": "Registration start date, format YYYY-MM-DD. Return null if not found."
          },
          "endDate": {
            "title": "End Date",
            "type": "string",
            "description": "Registration end date, format YYYY-MM-DD. Return null if not found."
          },
          "format": {
            "title": "Format",
            "type": "string",
            "enum": [
              "Online",
              "Offline",
              "Hybrid"
            ],
            "description": "Competition format. Return null if not found."
          },
          "participationType": {
            "title": "Participation Type",
            "type": "string",
            "enum": [
              "Individual",
              "Team"
            ],
            "description": "Participation type. Return null if not found."
          },
          "pricing": {
            "title": "Pricing",
            "type": "string",
            "description": "Registration fee in rupiah. Return null if not found."
          },
          "url": {
            "title": "URL",
            "type": "string",
            "description": "Registration URL. Return null if not found."
          },
          "location": {
            "title": "Location",
            "type": "string",
            "description": "Country of the competition. Return null if not found."
          }
        },
        "required": [
          "title",
          "organizer",
          "categories",
          "level",
          "startDate",
          "endDate",
          "format",
          "participationType",
          "pricing",
          "url",
          "location"
        ],
        "title": "Competition",
        "type": "object",
        "additionalProperties": false
      },
      "name": "competition",
      "strict": true
    }
  },
  "max_tokens": 512,
  "temperature": 0
}

